806.body:
This PR introduce exceptions for Hoare Logic.

We can define exception :
``` easycrypt
exception assume.
exception assert.
```

We can raise exception using `raise assume` or `if (x = 3) else raise assert` (raise an exception when a condition is not true):
``` easycrypt
module M ={
  proc f (x:int) : int = {
    if (x = 3) else raise assert;
    x <- 1;
    if (x = 3)  {
       raise assume;
    }
    if (x=3) {
        raise assert;
      }
  return x;
  }
}.
```

We can define postconditions for each exception and a default postcondition:
``` easycrypt
lemma assume_assert : hoare [M.f : pre ==> post | assume:p1 |assert: p2 | p3].
```

Examples are available in `examples/exception.ec`.

commits.body:
This tactic "inlines" tuple assignments, i.e. it transforms

```
(lv1,...,lvn) <- (e1,...,en);
```

in

```
lv1 <- e1;
...
lvn <- en;
```

Here is an example of use:

```
require import AllCore.

type t = [
  A of int | B of bool | C
].

module M = {
  proc f(x : t) : int = {
    var y : int <- 0;

    match x with
    | A v => y <- `|v|;
    | B _ => y <- 1;
    | C   => y <- 2;
    end;

    return y;
  }
}.

lemma L : hoare[M.f : true ==> 0 <= res].
proof. by proc; sp; match => [v|b|]; auto=> /> /#. qed.
```

Loops' epilogs must now be deterministic and loop/calls-free.

This forbids the following unsoundness:

```
require import AllCore DBool.

module E = {
  var i,j : int
  proc foo () = {
    var c;
    i <- 0;
    j <- 0;
    c <- false;
    while (!c) {
      i <- i + 1;
      j <- j + 1;
      c <$ {0,1};
    }
    return i = j;
  }

  proc bar () = {
    var c;
    i <- 0;
    j <- 0;
    c <- false;
    while (!c) {
      i <- i + 1;
      c <$ {0,1};
    }
    c <- false;
    while (!c) {
      j <- j + 1;
      c <$ {0,1};
    }
    return i = j;
  }
}.

equiv bad : E.foo ~ E.bar : true ==> ={res}.
proof.
proc.
fission{1} 4!1 @1,2. by sim.
qed.
```

Fix #210

The tactic statically unroll while loops of the form

  x <- int-constant
  while (guard) {
    body (does not write x);
    x <- f(x);
  }

where "guard" and "f" can be statically evaluated at each
iteration. The code is then replaced by the while loop
fully unrolled.

The tactic does not terminate if the unrolling leads to
a infinite process.

module type OT = {
  proc f(_: t): t'
  proc g1(_: t): t'
}.

module type MT (O : OT) = {
  include OT
  proc g(_: u): u'
}.

module type MT1 (O : OT) = {
  include OT [f]
  proc g(_: u): u'
}.

module type MT2 (O : OT) = {
  include OT [f] {O.f}
  proc g(_: u): u'
}.

module type MT3 (O : OT) = {
  include OT [f] {O.g1}
  proc g(_: u): u'
}.

module ((M : MT1):MT2) (O : OT) = {
  proc f = O.f

  proc g(x: u): u' = {
    return witness;
  }
}.

module M1 = {
  proc f () : unit = { }
  proc g () : unit = { }
}.

module M2 = {
  include M1
}.

module M3 = {
  include M1 [f]
}.

module M4 = {
  include M1 [+f]
}.

module M5 = {
  include M1 [-f]
}.

module F (O:OT) = {
  proc f1 () = {}
}.

module G (O:OT) = {
  include O
  include F(O)
}.

module G1 (O:OT) = {
  include O [-f]
  include F(O)
}.
